import React, { useState } from 'react';

interface Permission {
  id: number;
  name: string;
  allowed: boolean;
}

const PermissionSystem = () => {
  const [permissions, setPermissions] = useState<Permission[]>([
    { id: 1, name: 'Read', allowed: true },
    { id: 2, name: 'Write', allowed: false },
    { id: 3, name: 'Delete', allowed: true },
  ]);

  const togglePermission = (id: number) => {
    setPermissions(prev => prev.map(perm => 
      perm.id === id ? { ...perm, allowed: !perm.allowed } : perm
    ));
  };

  return (
    <div>
      <h1>Permission System</h1>
      {permissions.map(permission => (
        <div key={permission.id}>
          <span>{permission.name}</span>
          <button onClick={() => togglePermission(permission.id)}>
            {/* Set button text to 'Enable' or 'Disable' based on permission.allowed */}
          </button>
        </div>
      ))}
    </div>
  );
};

export default PermissionSystem;

